-- Fictional identities, isolated transaction. No persistent seed or live users.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) values
('00000000-0000-0000-0000-000000000101','fixture-a@nova.invalid','{"birth_date":"1995-01-01","consent_version":"draft-v1"}',now()),
('00000000-0000-0000-0000-000000000102','fixture-b@nova.invalid','{"birth_date":"1994-01-01","consent_version":"draft-v1"}',now()),
('00000000-0000-0000-0000-000000000103','fixture-c@nova.invalid','{"birth_date":"1993-01-01","consent_version":"draft-v1"}',now()),
('00000000-0000-0000-0000-000000000104','fixture-d@nova.invalid','{"birth_date":"1992-01-01","consent_version":"draft-v1"}',now());
update public.profiles set display_name='Fictional fixture',seeking_gender='any',onboarding_complete=true where id::text like '%00000000010_';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000101';
select lives_ok($$select public.save_profile('{"city":"Cairo","bio":"Private biography","languages":["Arabic"],"details":{"occupation":"Private occupation"},"public_fields":["languages"]}')$$,'expanded profile persists');
select is((select city from public.profiles),'Cairo','own city persisted');
select throws_ok($$select public.save_profile('{"birth_date":"2020-01-01"}')$$,'P0001','Adults 18+ only','DOB cannot bypass age');
select throws_ok($$select public.save_profile('{"details":{"administrator":"yes"}}')$$,'P0001','Invalid optional field','details cannot carry arbitrary fields');
select throws_ok($$select public.save_profile_core('{"verified":true}')$$,'42501',null,'legacy inner writer not exposed');
select is((select count(*)::int from public.profiles),1,'private profile table remains own only');
select throws_ok($$select public.save_discovery_filters('{"has_photo":true}')$$,'P0001','Advanced filters require Plus','advanced filters require server entitlement');
select lives_ok($$select public.save_discovery_filters('{"city":"Alexandria"}')$$,'free regional filter saves');
select is((select count(*)::int from public.discover_profiles()),0,'regional filter enforced on server');
select lives_ok($$select public.save_discovery_filters('{}')$$,'filters reset');
select is((select count(*)::int from public.discover_profiles()),3,'eligible real fixture profiles projected');
select throws_ok($$select public.discovery_action(auth.uid(),'like')$$,'P0001','Invalid action','self like denied');
select lives_ok($$select public.toggle_favorite('00000000-0000-0000-0000-000000000102',true)$$,'favorite added');
select lives_ok($$select public.toggle_favorite('00000000-0000-0000-0000-000000000102',true)$$,'favorite deduplicated');
select is((select count(*)::int from public.favorites),1,'one private favorite');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000102';
select is((select count(*)::int from public.favorites),0,'favorites invisible to target');
select ok(not(public.public_profile('00000000-0000-0000-0000-000000000101') ? 'city'),'hidden city not projected');
select ok(not(public.public_profile('00000000-0000-0000-0000-000000000101') ? 'email'),'private email not projected');
select is(public.public_profile('00000000-0000-0000-0000-000000000101')->'details','{}'::jsonb,'private occupation not projected');
select is(public.discovery_action('00000000-0000-0000-0000-000000000101','like'),false,'pending like created');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000101';
select is((public.interaction_overview()->>'incoming_count')::int,1,'free safe incoming count');
select is(jsonb_array_length(public.interaction_overview()->'incoming'),0,'free does not receive liker identity');
reset role;
update public.discovery_actions set expires_at=now()-interval '1 second' where actor_id='00000000-0000-0000-0000-000000000102';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000101';
select is((public.interaction_overview()->>'incoming_count')::int,0,'expired incoming removed without scheduler');
select is(public.discovery_action('00000000-0000-0000-0000-000000000102','like'),false,'expired like cannot form a match');
select is((select count(*)::int from public.matches),0,'expiration never implies a match');
select is(public.discovery_action('00000000-0000-0000-0000-000000000103','like'),false,'new pending pair');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000103';
select is(public.discovery_action('00000000-0000-0000-0000-000000000101','like'),true,'valid reciprocal match');
select lives_ok($$select public.send_message((select id from public.conversations limit 1),'Persistent fixture message')$$,'free mutual match may chat');
select ok(jsonb_array_length(public.notification_inbox()->'items')>=1,'match event is persistent');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000101';
select ok((public.notification_inbox()->>'unread')::int>=2,'unread includes own real events');
select lives_ok($$select public.read_notifications()$$,'mark all read');
select is((public.notification_inbox()->>'unread')::int,0,'read state persisted');
select is((select count(*)::int from public.notifications where user_id<>'00000000-0000-0000-0000-000000000101'),0,'notification RLS rejects unrelated reads');
select lives_ok($$select public.prepare_profile_photo('private')$$,'prepare private photo');
select throws_ok($$select public.finalize_profile_photo((select id from public.profile_photos limit 1))$$,'P0001','Upload not completed or invalid file','local preview cannot finalize missing upload');
select throws_ok($$insert into public.profile_photos(owner_id,path) values(auth.uid(),auth.uid()::text||'/forged.jpg')$$,'42501',null,'photo metadata cannot be forged directly');
select ok(not (public.membership_status()->>'purchases_enabled')::bool,'payments disabled');
select ok(not (public.membership_status()->>'trial_enabled')::bool,'no live trial activated');
select is((select count(*)::int from public.membership_offers),9,'configurable free and duration catalog');
select throws_ok($$insert into public.entitlements(user_id,feature,expires_at) values(auth.uid(),'premium',now()+interval '1 year')$$,'42501',null,'client cannot grant Premium');
select lives_ok($$select public.referral_progress()$$,'real invitation code issued');
select throws_ok($$select public.claim_referral(public.referral_progress()->>'code')$$,'P0001','Invalid invitation','self referrals rejected');
select throws_ok($$select public.grant_referral_reward(gen_random_uuid())$$,'42501',null,'client cannot fabricate referral reward');
select throws_ok($$select public.review_referral(gen_random_uuid(),true)$$,'P0001','Forbidden','ordinary user cannot review referrals');
select ok(not (public.referral_progress()->>'rewards_enabled')::bool,'rewards pending approval');
select lives_ok($$select public.request_account_deletion()$$,'deletion request saves without erasing conversations');
select is((select count(*)::int from public.messages),1,'deletion request preserves messages during grace period');
select lives_ok($$select public.request_account_deletion(true)$$,'owner may cancel during grace period');
select ok(public.export_my_data()->'profile'->>'id'=auth.uid()::text,'export restricted to authenticated profile');
select lives_ok($$select public.end_match((select id from public.conversations limit 1))$$,'unmatch state saved');
select is((select count(*)::int from public.messages),0,'unmatched conversation no longer readable');
reset role;
select is((select count(*)::int from public.messages),1,'unmatch preserves history on server');
select * from finish();
rollback;
